# Generated by build.py from recipe.yml for recipe ftp-abort-from-a-progress-callback. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'mkdir -p site'
cmd /c 'head -c 1000000 /dev/urandom > site/slow.bin'
cmd /c 'cp site/slow.bin site/fast.bin'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'site', '--fault', '"delay;stage=command;command=RETR;path=/slow.bin;ms=3000"', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { dotnet run fetch.cs -- ftp://127.0.0.1:8080/slow.bin 1 } finally { Stop-Process $server0 }
